from pathlib import Path
import re
root=Path('ERP-INTEGRAL-4.0-SUPABASE-MIGRADO')
app=root/'public/app.js'; metas=root/'public/metas-v2.js'; index=root/'public/index.html'; css=root/'public/metas-v2.css'

# app.js
s=app.read_text()
s=s.replace("const USER_TYPES=['Administrador','Comercial','Projetos','Topografia','Marketing','Pós-protocolo','Atendimentos','Diretor Técnico'];","const USER_TYPES=['Administrador','Comercial','Financeiro','Projetos','Topografia','Marketing','Pós-protocolo','Atendimentos','Diretor Técnico'];")
s=s.replace("const USER_SECTORS=['Administrativo','Comercial','Projetos','Topografia','Marketing','Pós-protocolo','Atendimentos'];","const USER_SECTORS=['Administrativo','Comercial','Financeiro','Projetos','Topografia','Marketing','Pós-protocolo','Atendimentos'];")
marker="let remoteLoaded=false;"
if 'PROJECT_GROUPS_STORAGE' not in s:
    s=s.replace(marker,marker+"\nconst PROJECT_GROUPS_STORAGE='erp_integral_project_groups_collapsed';\nlet collapsedProjectGroups=(()=>{try{return JSON.parse(localStorage.getItem(PROJECT_GROUPS_STORAGE)||'{}')}catch{return {}}})();\nfunction setProjectGroupCollapsed(key,value){collapsedProjectGroups[key]=value;try{localStorage.setItem(PROJECT_GROUPS_STORAGE,JSON.stringify(collapsedProjectGroups))}catch{}}")
old='`<section class="project-group"><div class="group-title">${t} <span>${groups[t].length}</span></div><div class="table-wrap">'
new='`<section class="project-group ${collapsedProjectGroups[t]?\'collapsed\':\'\'}" data-project-group="${esc(t)}"><div class="group-title"><button type="button" class="project-group-toggle" data-toggle-project-group="${esc(t)}" aria-expanded="${collapsedProjectGroups[t]?\'false\':\'true\'}"><span class="chev">⌄</span><span>${t}</span><span>${groups[t].length}</span></button></div><div class="table-wrap">'
s=s.replace(old,new)
hook="$$('[data-del-project]').forEach(b=>b.onclick=()=>deleteProject(b.dataset.delProject));"
if "setProjectGroupCollapsed(key" not in s[s.find(hook):s.find(hook)+800]:
    s=s.replace(hook,hook+"\n  $$('[data-toggle-project-group]').forEach(b=>b.onclick=()=>{const key=b.dataset.toggleProjectGroup;setProjectGroupCollapsed(key,!collapsedProjectGroups[key]);renderProjects()});")
if 'function changeOwnPassword' not in s:
    own='''\nasync function changeOwnPassword(){\n  openModal('Alterar minha senha',`<form id="ownPasswordForm" class="form-grid"><div class="field full"><label>Nova senha</label><input name="password" type="password" autocomplete="new-password" minlength="8" required></div><div class="field full"><label>Confirmar nova senha</label><input name="confirm" type="password" autocomplete="new-password" minlength="8" required></div><div id="ownPasswordStatus" class="field full muted">Use pelo menos 8 caracteres.</div></form>`,()=>$('#ownPasswordForm').requestSubmit());\n  $('#ownPasswordForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),password=String(fd.get('password')||''),confirm=String(fd.get('confirm')||''),status=$('#ownPasswordStatus');if(password.length<8){status.textContent='A senha precisa ter pelo menos 8 caracteres.';return}if(password!==confirm){status.textContent='As senhas não coincidem.';return}const btn=$('#modalSave');btn.disabled=true;btn.textContent='Alterando...';const {error}=await sb.auth.updateUser({password});if(error){status.textContent=error.message;btn.disabled=false;btn.textContent='Salvar';return}status.textContent='Senha alterada com sucesso.';btn.textContent='Concluído';setTimeout(closeModal,700)};\n}\n\n'''
    s=s.replace('function renderApp(){',own+'function renderApp(){',1)
s=s.replace('<div class="sidebar-foot"><div class="user-mini"><strong>${esc(currentUser.name)}</strong>${esc(currentUser.type)}</div><button id="logout" class="btn secondary wide">Sair</button></div>','<div class="sidebar-foot"><div class="user-mini"><strong>${esc(currentUser.name)}</strong>${esc(currentUser.type)}</div><button id="changeMyPassword" class="security-link-btn" type="button">Alterar minha senha</button><button id="logout" class="btn secondary wide">Sair</button></div>')
s=s.replace("$('#logout').onclick=async()=>{await sb.auth.signOut();renderLogin();};","$('#changeMyPassword').onclick=changeOwnPassword;\n  $('#logout').onclick=async()=>{await sb.auth.signOut();renderLogin();};")
app.write_text(s)

# metas-v2.js
m=metas.read_text()
if 'function allowedProfessional' not in m:
    marker="const canManageSectors=()=>canManageMeta();"
    m=m.replace(marker,marker+"\nfunction allowedProfessional(u){const t=normRole(u?.type||u?.role||'');return t.includes('projet')||t.includes('topografia')||t.includes('pos protocolo');}")
m=m.replace("db().users.filter(u=>u.active):[currentUser()]","db().users.filter(u=>u.active&&allowedProfessional(u)):[currentUser()]")
m=m.replace("db().users.filter(u=>u.active).map(u=>`<label class=\"check-item\">","db().users.filter(u=>u.active&&allowedProfessional(u)).map(u=>`<label class=\"check-item\">")
m=m.replace("<option value=\"projeto\" ${assocType==='projeto'?'selected':''}>Projeto do ERP</option>","")
if 'async function loadMetaCollaboration' not in m:
    collab=r'''\nasync function loadMetaCollaboration(metaId){const client=sb();const [c,k]=await Promise.all([client.from('meta_comentarios').select('*').eq('meta_id',metaId).order('created_at'),client.from('meta_checklist').select('*').eq('meta_id',metaId).order('created_at')]);if(c.error)throw c.error;if(k.error)throw k.error;return {comments:c.data||[],checklist:k.data||[]}}\nfunction canCollaborateMeta(m){return canManageMeta()||m.created_by===currentUser()?.id||metaResponsibles(m.id).includes(currentUser()?.id)}\nasync function wireMetaCollaboration(m){const modal=qs('#modal .modal');if(!modal)return;let data;try{data=await loadMetaCollaboration(m.id)}catch(e){console.warn('Colaboração da meta:',e);return}const tabs=qs('.metas-tabs',modal),actions=qs('.meta-admin-actions',modal)||qs('.modal-foot',modal);if(!tabs||!actions)return;tabs.insertAdjacentHTML('beforeend',`<button class="metas-tab" data-v2tab="checklist">Checklist (${data.checklist.length})</button><button class="metas-tab" data-v2tab="comments">Comentários (${data.comments.length})</button>`);const check=document.createElement('div');check.className='metas-tab-panel hidden';check.dataset.v2panel='checklist';const comments=document.createElement('div');comments.className='metas-tab-panel hidden';comments.dataset.v2panel='comments';actions.parentNode.insertBefore(check,actions);actions.parentNode.insertBefore(comments,actions);const can=canCollaborateMeta(m);check.innerHTML=`<div class="meta-checklist-list">${data.checklist.length?data.checklist.map(x=>`<div class="meta-check-item ${x.concluido?'done':''}" data-check-id="${x.id}"><input type="checkbox" ${x.concluido?'checked':''} ${can?'':'disabled'}><div class="meta-check-text"><strong>${esc(x.titulo)}</strong>${x.concluido?`<div class="meta-check-meta">Concluído por ${esc(userName(x.concluido_por))}</div>`:''}</div>${can?'<button type="button" class="meta-check-delete">×</button>':''}</div>`).join(''):'<div class="empty compact">Nenhum item no checklist.</div>'}</div>${can?'<div class="meta-collab-add"><input id="newMetaChecklistItem" placeholder="Novo item do checklist"><button type="button" class="btn secondary" id="addMetaChecklistItem">Adicionar item</button></div>':''}`;comments.innerHTML=`<div class="meta-comments-list">${data.comments.length?data.comments.map(c=>`<div class="meta-comment-item"><div class="meta-comment-head"><strong>${esc(userName(c.autor_id))}</strong><span class="muted">${new Date(c.created_at).toLocaleString('pt-BR')}</span></div><p>${esc(c.texto)}</p></div>`).join(''):'<div class="empty compact">Nenhum comentário.</div>'}</div>${can?'<div class="meta-collab-add"><textarea id="newMetaComment" rows="3" placeholder="Escreva um comentário..."></textarea><button type="button" class="btn secondary" id="addMetaComment">Enviar comentário</button></div>':''}`;qsa('[data-v2tab]',modal).forEach(t=>t.onclick=()=>{qsa('[data-v2tab]',modal).forEach(x=>x.classList.remove('active'));t.classList.add('active');qsa('[data-v2panel]',modal).forEach(p=>p.classList.toggle('hidden',p.dataset.v2panel!==t.dataset.v2tab))});if(!can)return;qsa('.meta-check-item',check).forEach(row=>{const input=qs('input',row);input.onchange=async()=>{const done=input.checked,r=await sb().from('meta_checklist').update({concluido:done,concluido_por:done?currentUser().id:null,concluido_em:done?new Date().toISOString():null,updated_at:new Date().toISOString()}).eq('id',row.dataset.checkId).select().single();if(r.error){alert(r.error.message);input.checked=!done;return}await historyAdd(m,{acao:done?'Checklist concluído':'Checklist reaberto',descricao:r.data.titulo});B().closeModal();metaDetail(m.id)};qs('.meta-check-delete',row)?.addEventListener('click',async()=>{if(!confirm('Excluir este item do checklist?'))return;const r=await sb().from('meta_checklist').delete().eq('id',row.dataset.checkId);if(r.error){alert(r.error.message);return}await historyAdd(m,{acao:'Checklist removido',descricao:'Item removido do checklist.'});B().closeModal();metaDetail(m.id)})});qs('#addMetaChecklistItem',check)?.addEventListener('click',async()=>{const inp=qs('#newMetaChecklistItem',check),titulo=inp.value.trim();if(!titulo)return;const r=await sb().from('meta_checklist').insert({id:uid(),meta_id:m.id,titulo,created_by:currentUser().id}).select().single();if(r.error){alert(r.error.message);return}await historyAdd(m,{acao:'Checklist adicionado',descricao:titulo});B().closeModal();metaDetail(m.id)});qs('#addMetaComment',comments)?.addEventListener('click',async()=>{const inp=qs('#newMetaComment',comments),texto=inp.value.trim();if(!texto)return;const r=await sb().from('meta_comentarios').insert({id:uid(),meta_id:m.id,autor_id:currentUser().id,texto}).select().single();if(r.error){alert(r.error.message);return}await historyAdd(m,{acao:'Comentário adicionado',descricao:texto.length>120?texto.slice(0,120)+'…':texto});B().closeModal();metaDetail(m.id)})}\n\n'''
    m=m.replace('function renderLoading()',collab+'function renderLoading()',1)
md=re.search(r"function metaDetail\(id\)\{.*?\}\nfunction weekEndFromStart",m,re.S)
if not md: raise SystemExit('metaDetail nao localizado')
block=md.group(0)
if 'wireMetaCollaboration(m)' not in block:
    needle="qsa('[data-open-meta-file]').forEach(b=>b.onclick=()=>openMetaFile(state.files.find(f=>f.id===b.dataset.openMetaFile)))}\nfunction weekEndFromStart"
    repl="qsa('[data-open-meta-file]').forEach(b=>b.onclick=()=>openMetaFile(state.files.find(f=>f.id===b.dataset.openMetaFile)));wireMetaCollaboration(m)}\nfunction weekEndFromStart"
    if needle not in block: raise SystemExit('fim de metaDetail nao localizado')
    block=block.replace(needle,repl)
    m=m[:md.start()]+block+m[md.end():]
metas.write_text(m)

# css
c=css.read_text()
if '.meta-checklist-list' not in c:
    c+='\n.meta-checklist-list,.meta-comments-list{display:grid;gap:8px}.meta-check-item{display:flex;align-items:center;gap:10px;border:1px solid var(--line,#d9e4e2);padding:10px 12px;border-radius:10px;background:#fff}.meta-check-item.done .meta-check-text{text-decoration:line-through;opacity:.62}.meta-check-item input{width:18px;height:18px}.meta-check-text{flex:1;min-width:0}.meta-check-meta{font-size:11px;color:var(--muted,#70807e)}.meta-collab-add{display:flex;gap:8px;margin-top:12px}.meta-collab-add input,.meta-collab-add textarea{flex:1;min-width:0}.meta-comment-item{border-left:3px solid #7bbdb6;background:#f8fbfb;border-radius:0 10px 10px 0;padding:10px 12px}.meta-comment-head{display:flex;justify-content:space-between;gap:10px;margin-bottom:5px}.meta-comment-item p{margin:0;white-space:pre-wrap}.meta-check-delete{border:0;background:transparent;cursor:pointer;font-size:18px;opacity:.6}.meta-check-delete:hover{opacity:1}\n'
css.write_text(c)

# index
i=index.read_text()
for name in ['account-security.js?v=14','financeiro-sector.js?v=14','meta-collaboration.js?v=14','erp-ui-enhancements.js?v=14']:
    i=re.sub(r'\s*<script src="'+re.escape(name)+r'"></script>','',i)
i=i.replace('styles.css?v=14','styles.css?v=16').replace('metas-v2.css?v=15','metas-v2.css?v=16').replace('app.js?v=15','app.js?v=16').replace('erp-bridge.js?v=14','erp-bridge.js?v=16').replace('metas-v2.js?v=15','metas-v2.js?v=16')
index.write_text(i)
